function formatDate(value) {
	if (!value) return "—";
	const d = new Date(value);
	if (Number.isNaN(d.getTime())) return "—";
	return new Intl.DateTimeFormat("ar-EG", {
		year: "numeric",
		month: "2-digit",
		day: "2-digit",
		numberingSystem: "latn"
	}).format(d);
}
